  const shellArgv=structuredClone(bundles[0]!),shellArgvVersion=shellArgv.version as Record<string,unknown>,shellArgvExecutable=shellArgvVersion.executable as Record<string,unknown>;shellArgvExecutable.fixedArgv=["run","output > /tmp/result"];shellArgvVersion.digest=harnessVersionDigest(shellArgvVersion);assert.match(verifyHarnessBundle(shellArgv).join(" "),/shell syntax/);
  for(const path of ["/usr/bin/python3.12","/opt/reviewed/node-v24","/usr/local/bin/curl-wrapper"]){const alias=structuredClone(bundles[0]!),aliasVersion=alias.version as Record<string,unknown>,aliasExecutable=aliasVersion.executable as Record<string,unknown>;aliasExecutable.path=path;aliasVersion.digest=harnessVersionDigest(aliasVersion);assert.match(verifyHarnessBundle(alias).join(" "),/reviewed adapter identity and path/,path);}
  const provenanceTamper=structuredClone(bundles[0]!);((provenanceTamper.version as Record<string,Record<string,unknown>>).provenance!).commit="2".repeat(40);assert.match(verifyHarnessBundle(provenanceTamper).join(" "),/semantic digest/);
