  const claudeWithoutAuthorization=structuredClone(bundles[2]!);(claudeWithoutAuthorization.profile as Record<string,unknown>).directProviderAuthorization=null;(claudeWithoutAuthorization.profile as Record<string,unknown>).digest=harnessProfileDigest(claudeWithoutAuthorization.profile);assert.match(verifyHarnessBundle(claudeWithoutAuthorization).join(" "),/resolved same-workspace approved DIRECT authorization/);
  const substitutedAuthorization=structuredClone(bundles[2]!),substitutedProfile=substitutedAuthorization.profile as Record<string,unknown>,authorization=substitutedProfile.directProviderAuthorization as Record<string,unknown>;authorization.workspaceId="40000000-0000-4000-8000-000000000099";substitutedProfile.digest=harnessProfileDigest(substitutedProfile);assert.match(verifyHarnessBundle(substitutedAuthorization).join(" "),/same-workspace/);
  const duplicateDeclaration=structuredClone(bundles[0]!),duplicateProfile=duplicateDeclaration.profile as Record<string,unknown>,duplicateCredentials=duplicateProfile.credentials as Array<Record<string,unknown>>;duplicateCredentials.push({...duplicateCredentials[0]!,leaseSeconds:1200});duplicateProfile.digest=harnessProfileDigest(duplicateProfile);assert.match(verifyHarnessBundle(duplicateDeclaration).join(" "),/declarations must be unique/);
  const agentTamper=structuredClone(agent);(agentTamper.version as Record<string,unknown>).instructions="substituted";assert.match(verifyAgentCompatibility(agentTamper,bundles).join(" "),/AgentVersion semantic digest/);
  const republishedProfile=structuredClone(bundles[0]!),republishedProfileValue=republishedProfile.profile as Record<string,unknown>;((republishedProfileValue.overrides as Record<string,unknown>)).format="yaml";republishedProfileValue.digest=harnessProfileDigest(republishedProfileValue);assert.match(verifyAgentCompatibility(agent,[republishedProfile,...bundles.slice(1)]).join(" "),/immutable AgentVersion pin/);
