  const evaluationDrift=structuredClone(parity[0]!);(evaluationDrift.portableEvaluation as Record<string,unknown>).id="90000000-0000-4000-8000-000000000099";assert.match(verifyPortableEvaluation(evaluationDrift,parityBundles[0],agent).join(" "),/authoritative portable AgentVersion/);
  const evidenceWorkspaceDrift=structuredClone(parity[0]!);((evidenceWorkspaceDrift.result as {evidenceArtifacts:Array<Record<string,unknown>>}).evidenceArtifacts[0]!).workspaceId="40000000-0000-4000-8000-000000000099";assert.match(verifyPortableEvaluation(evidenceWorkspaceDrift,parityBundles[0],agent).join(" "),/workspace/);
